CREATE TABLE [dbo].[TREC_HORARIOS](	  [hora_id] INT NOT NULL IDENTITY(1,1)	, [hora_nombre] VARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [horaini] VARCHAR(10) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [horafin] VARCHAR(10) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [lunes] BIT NOT NULL DEFAULT((0))	, [martes] BIT NOT NULL DEFAULT((0))	, [miercoles] BIT NOT NULL DEFAULT((0))	, [jueves] BIT NOT NULL DEFAULT((0))	, [viernes] BIT NOT NULL DEFAULT((0))	, [sabado] BIT NOT NULL DEFAULT((0))	, [domingo] BIT NOT NULL DEFAULT((0))	, CONSTRAINT [PK_TREC_TPL_HORARIOS] PRIMARY KEY ([hora_id] ASC))